/** Returns how a member hears from the library: 'sms' when they chose it and gave a phone number, else 'email'. */
export function channelFor(member) {
  return member.notify === 'sms' && member.phone ? 'sms' : 'email';
}

/** Returns where a notice by this channel goes: the member's phone number or email address. */
export function addressFor(member, channel) {
  return channel === 'sms' ? member.phone : member.email;
}
import { fillTemplate } from '../helpers/text.js';
import { displayName } from '../members/accounts.js';
import { addressFor, channelFor } from './channels.js';
import { TEMPLATES } from './templates.js';

/**
 * Builds a notice of one kind for a member: { channel, to, subject, body }. The subject is null
 * for a text message, which has none.
 */
export function composeNotice(kind, { member, values }) {
  const template = TEMPLATES[kind];
  if (template === undefined) throw new Error(`Unknown notice kind ${kind}`);
  const channel = channelFor(member);
  return {
    channel,
    to: addressFor(member, channel),
    subject: channel === 'email' ? template.subject : null,
    body: fillTemplate(template.body, { name: displayName(member), ...values }),
  };
}
import { addDays, daysBetween } from '../helpers/dates.js';
import { listOverdueLoans } from '../reports/overdue.js';
import { composeNotice } from './compose.js';

/** Loans due within this many days get a reminder in the morning run. */
const DUE_SOON_DAYS = 2;

/** Returns the reminders of the morning run for loans that fall due within two days of today. */
export function dueSoonNotices(store, today) {
  const until = addDays(today, DUE_SOON_DAYS);
  return store
    .listAllLoans()
    .filter((loan) => loan.returnedOn === null && loan.dueOn >= today && loan.dueOn <= until)
    .map((loan) => noticeFor(store, 'dueSoon', loan));
}

/** Returns the notices of the morning run for loans that are overdue today. */
export function overdueNotices(store, today) {
  return listOverdueLoans(store, today).map((loan) => {
    const daysLate = daysBetween(loan.dueOn, today);
    return noticeFor(store, 'overdue', loan, { daysLate: `${daysLate} ${daysLate === 1 ? 'day' : 'days'}` });
  });
}

function noticeFor(store, kind, loan, extraValues = {}) {
  const member = store.getMember(loan.memberId);
  const item = store.getItem(loan.itemId);
  return composeNotice(kind, { member, values: { title: item.title, dueOn: loan.dueOn, ...extraValues } });
}
/** The text of each kind of notice; {name} and the other placeholders are filled in when it is sent. */
export const TEMPLATES = {
  holdReady: {
    subject: 'Your hold is ready',
    body: 'Hello {name}, "{title}" is waiting for you at {branch}. Please collect it by {deadline}.',
  },
  dueSoon: {
    subject: 'An item is due soon',
    body: 'Hello {name}, "{title}" is due back on {dueOn}. You can renew it online.',
  },
  overdue: {
    subject: 'An item is overdue',
    body: 'Hello {name}, "{title}" was due back on {dueOn}. It is {daysLate} late. Please return it to any branch.',
  },
};
/** Lower-cases text and turns every run of punctuation and spaces into one space, for matching. */
export function normaliseText(text) {
  return text
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .trim();
}

/** Replaces each {name} in a template by the value of that name; unknown names stay as they are. */
export function fillTemplate(template, values) {
  return template.replace(/\{(\w+)\}/g, (placeholder, name) =>
    name in values ? String(values[name]) : placeholder,
  );
}
import { branchById } from '../config/branches.js';
import { composeNotice } from '../notices/compose.js';
import { pickupDeadline } from './pickup.js';

/** Returns the notice that tells a member their hold is ready to collect. */
export function holdReadyNotice(store, hold) {
  const member = store.getMember(hold.memberId);
  const item = store.getItem(hold.itemId);
  return composeNotice('holdReady', {
    member,
    values: {
      title: item.title,
      branch: branchById(hold.pickupBranchId).name,
      deadline: pickupDeadline(hold),
    },
  });
}
