  const base = composeNotice('dueSoon', { member: BEN, values: { title: '', dueOn: '2026-11-27' } });
  const title = 'B'.repeat(160 - base.body.length);
  const notice = composeNotice('dueSoon', { member: BEN, values: { title, dueOn: '2026-11-27' } });
  assert.equal(notice.body.length, 160);
  assert.ok(!notice.body.endsWith('...'));
});

test('a notice by email is never shortened', () => {
  const title = 'A'.repeat(200);
  const notice = composeNotice('dueSoon', { member: ADA, values: { title, dueOn: '2026-11-27' } });
  assert.ok(notice.body.length > 160);
  assert.ok(notice.body.includes(title));
});

